// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/// @title AlexandriaLibrary - Central registry for all uploads to Alexandria
contract AlexandriaLibrary is Ownable, Pausable {

    // Upload validation states
    enum UploadStatus { Pending, Challenged, Approved, Rejected }

    // Metadata for each upload
    struct Upload {
        string arweaveHash;     // Arweave transaction ID (43-char Base64URL)
        address uploader;       // Archivist who uploaded the content
        uint256 timestamp;      // Block timestamp when registered
        UploadStatus status;    // Current validation state
        string metadata;        // Title, author, or other descriptive info
    }

    // arweaveHash => Upload details
    mapping(string => Upload) private uploads;

    // uploader address => list of their arweave hashes
    mapping(address => string[]) private uploaderHashes;

    // Addresses banned from uploading (malicious archivists)
    mapping(address => bool) public blacklisted;

    // Authorized contract addresses that can register or update uploads
    mapping(address => bool) public authorizedCallers;

    // Events
    event UploadRegistered(string indexed arweaveHash, address indexed uploader, string metadata);
    event UploadStatusChanged(string indexed arweaveHash, UploadStatus oldStatus, UploadStatus newStatus);
    event AuthorizedCallerSet(address indexed caller, bool authorized);
    event AddressBlacklisted(address indexed uploader);

    // Modifiers, only allow owner or authorized contracts to call certain functions
    modifier onlyAuthorized() {
        require(authorizedCallers[msg.sender] || msg.sender == owner(), "Not authorized");
        _;
    }

    constructor() Ownable(msg.sender) {}

    // --- Admin Functions ---

    // Owner adds/removes authorized callers (backend, stake contract, etc.)
    
    function setAuthorizedCaller(address caller, bool authorized) external onlyOwner {
        authorizedCallers[caller] = authorized;
        emit AuthorizedCallerSet(caller, authorized);
    }

    function blacklistUploader(address uploader) external onlyAuthorized {
        require(uploader != address(0), "Invalid address");
        require(!blacklisted[uploader], "Already blacklisted");
        blacklisted[uploader] = true;
        emit AddressBlacklisted(uploader);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // --- Core Functions ---

    // Register a new upload after it has been stored on Arweave. This contract is being called by the backend after successful upload to Arweave and initial validation.
    function registerUpload(string calldata arweaveHash, address uploader, string calldata metadata) external onlyAuthorized whenNotPaused {
        // check to make sure arweaveHash is not empty
        require(bytes(arweaveHash).length > 0, "Empty arweave hash");
        // check to make sure uploader is not zero address
        require(uploader != address(0), "Invalid uploader address");
        // check if uploader is blacklisted
        require(!blacklisted[uploader], "Uploader is blacklisted");
        //check if upload already exists
        require(uploads[arweaveHash].timestamp == 0, "Upload already registered");
        // we pass the metadata in the struct
        uploads[arweaveHash] = Upload({
            arweaveHash: arweaveHash,
            uploader: uploader,
            timestamp: block.timestamp,
            status: UploadStatus.Pending,
            metadata: metadata
        });

        // we also keep track of all uploads by an uploader, so we can easily query them later. Might remove this since we are using MongoDB to index the uploads and we can just query by uploader there, but it doesn't hurt to have it on chain as well for easy retrieval without needing to query the database
        uploaderHashes[uploader].push(arweaveHash);
        // we emit the metadata in the event for easier indexing and retrieval by the frontend, since we won't be able to read the metadata from the contract directly without a lot of gas
        emit UploadRegistered(arweaveHash, uploader, metadata);
    }

    // Update upload status (called by stake contract during challenge/resolution)
    function updateUploadStatus(string calldata arweaveHash, UploadStatus newStatus) external onlyAuthorized whenNotPaused {
        // check if upload already exists
        require(uploads[arweaveHash].timestamp != 0, "Upload not found");

        UploadStatus oldStatus = uploads[arweaveHash].status;
        // require that the status is actually changing
        require(oldStatus != newStatus, "Status unchanged");

        uploads[arweaveHash].status = newStatus;
        // emit to the front end with the upload hash and the new status, so the front end can update the UI accordingly
        emit UploadStatusChanged(arweaveHash, oldStatus, newStatus);
    }

    // --- View Functions ---

    // Get full upload details
    function getUpload(string calldata arweaveHash) external view returns (Upload memory) {
        require(uploads[arweaveHash].timestamp != 0, "Upload not found");
        return uploads[arweaveHash];
    }

    // Get upload status only
    function getUploadStatus(string calldata arweaveHash) external view returns (UploadStatus) {
        require(uploads[arweaveHash].timestamp != 0, "Upload not found");
        return uploads[arweaveHash].status;
    }

    // Get the uploader address for an upload
    function getUploader(string calldata arweaveHash) external view returns (address) {
        require(uploads[arweaveHash].timestamp != 0, "Upload not found");
        return uploads[arweaveHash].uploader;
    }

    // Check if an upload exists
    function uploadExists(string calldata arweaveHash) external view returns (bool) {
        return uploads[arweaveHash].timestamp != 0;
    }

    // Get all arweave hashes uploaded by an address
    function getUploaderHashes(address uploader) external view returns (string[] memory) {
        return uploaderHashes[uploader];
    }
}

contracts/payment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./library.sol";
import "./token.sol";
import "./stake.sol";

// This contract handles all revenue distribution for the Alexandria protocol.
// It is the only contract that splits and disburses ALEX tokens to archivists, librarians, and the treasury.
// Rent.sol and Stake.sol forward payments here — neither pays out directly.

// Payment splits:
// - Rental revenue:  70% archivist / 20% treasury / 10% librarian pool
// - Upload reward:   50 ALEX fixed per valid upload (paid from treasury)
// - Slash (archivist stake rejected): 70% challenger / 30% burned
// - Wrong challenge (librarian slashed): 50% to archivist / 50% stays with librarian

// Design: pull pattern — rewards accumulate in mappings, recipients claim when ready (not pushed automatically)

contract AlexandriaPayment is Ownable, Pausable, ReentrancyGuard {

    AlexandriaLibrary public libraryContract;
    AlexandriaToken public tokenContract;
    AlexandriaStake public stakeContract;

    // Authorized contracts that can trigger payment distribution (Rent.sol, Stake.sol)
    mapping(address => bool) public authorizedCallers;

    // Revenue split constants
    uint256 public constant ARCHIVIST_SHARE = 70;
    uint256 public constant TREASURY_SHARE = 20;
    uint256 public constant LIBRARIAN_POOL_SHARE = 10;
    uint256 public constant UPLOAD_REWARD = 50 * 10 ** 18; // 50 ALEX fixed per valid upload

    // Treasury address (receives protocol fees)
    address public treasury;

    // Archivist pending rewards (pull pattern)
    mapping(address => uint256) public pendingArchivistRewards;

    // Tracks whether the upload reward has been paid out for a given arweaveHash
    mapping(string => bool) public uploadRewardClaimed;

    // Librarian reward accounting — rewards-per-token-staked pattern (Synthetix-style)
    // rewardPerTokenStored grows each time rental revenue is distributed.
    // Each librarian's share = their stake × (rewardPerTokenStored − their last snapshot rate).
    uint256 public rewardPerTokenStored;                        // scaled by 1e18 for precision
    mapping(address => uint256) public userRewardPerTokenPaid;  // rate at last snapshot per librarian
    mapping(address => uint256) public librarianEarned;         // accumulated unclaimed rewards

    // Events
    event RentalPaymentProcessed(string indexed arweaveHash, address indexed renter, uint256 amount);
    event UploadRewardDistributed(string indexed arweaveHash, address indexed archivist, uint256 amount);
    event RewardClaimed(address indexed recipient, uint256 amount);
    event AuthorizedCallerSet(address indexed caller, bool authorized);

    constructor(address _libraryAddress, address _tokenAddress, address _treasury) Ownable(msg.sender) {
        libraryContract = AlexandriaLibrary(_libraryAddress);
        tokenContract = AlexandriaToken(_tokenAddress);
        treasury = _treasury;
    }

    // --- Access Control ---

    modifier onlyAuthorized() {
        require(authorizedCallers[msg.sender], "Not authorized");
        _;
    }

      // Snapshots latest earned rewards before claiming — ensures no rewards are missed
    // between the last stake change and the claim.
    modifier updateReward(address librarian) {
        if (address(stakeContract) != address(0)) {
            _snapshotRewards(librarian);
        }
        _;
    }
    // setting contracts for authorized callers (Rent.sol, Stake.sol)
    function setAuthorizedCaller(address caller, bool authorized) external onlyOwner {
        require(caller != address(0), "Zero address");
        authorizedCallers[caller] = authorized;
        emit AuthorizedCallerSet(caller, authorized);
    }

    // --- Librarian Reward Accounting ---

    // Grows the global reward rate when new rental revenue arrives.
    // If no librarians are staked, the librarian share falls back to treasury.
    function _updateRewardRate(uint256 newRewards) internal {
        // check
        if (address(stakeContract) == address(0)) {
            tokenContract.transfer(treasury, newRewards);
            return;
        }
        uint256 totalStake = stakeContract.totalLibrarianStake();
        if (totalStake == 0) {
            tokenContract.transfer(treasury, newRewards);
            return;
        }
        rewardPerTokenStored += (newRewards * 1e18) / totalStake;
    }

    // Returns how much a librarian has earned since their last snapshot.
    function earned(address librarian) public view returns (uint256) {
        if (address(stakeContract) == address(0)) return librarianEarned[librarian];
        uint256 stake = stakeContract.getLibrarianStake(librarian);
        return (stake * (rewardPerTokenStored - userRewardPerTokenPaid[librarian])) / 1e18
               + librarianEarned[librarian];
    }

    //snapshots the librarian's earned rewards and updates their paid rate to the current global rate.
    function _snapshotRewards(address librarian) private {
        librarianEarned[librarian] = earned(librarian);
        userRewardPerTokenPaid[librarian] = rewardPerTokenStored;
    }



    // Called by stake.sol before any librarian stake change (stake / unstake / slash).
    // Locks in the librarian's earnings at the current rate before their share of
    // totalLibrarianStake changes and would distort future calculations.
    function notifyStakeChange(address librarian) external {
        require(msg.sender == address(stakeContract), "Not stake contract");
        _snapshotRewards(librarian);
    }

    // --- Core Distribution Functions ---

    // Called by Rent.sol when a user rents a book.
    // Renter must have approved this contract to spend `amount` tokens before Rent.sol calls this.
    function processRentalPayment(string memory arweaveHash, address renter, uint256 amount)
        external onlyAuthorized whenNotPaused
    {
        require(amount > 0, "Zero amount");

        address archivist = libraryContract.getUploader(arweaveHash);

        uint256 archivistAmount = (amount * ARCHIVIST_SHARE) / 100;
        uint256 librarianAmount = (amount * LIBRARIAN_POOL_SHARE) / 100;
        // Remainder absorbs rounding dust — goes to treasury
        uint256 treasuryAmount = amount - archivistAmount - librarianAmount;

        pendingArchivistRewards[archivist] += archivistAmount;
        _updateRewardRate(librarianAmount);
        tokenContract.transfer(treasury, treasuryAmount);

        emit RentalPaymentProcessed(arweaveHash, renter, amount);
    }

    // Called by Stake.sol when unstake() succeeds (valid upload approved after 14 days).
    // Treasury must have approved this contract to spend UPLOAD_REWARD on its behalf.
    // Rewards go to Archivist -
    function distributeUploadReward(string memory arweaveHash)
        external onlyAuthorized whenNotPaused
    {
        // checks arweavehash has not been rewarded already
        require(!uploadRewardClaimed[arweaveHash], "Reward already claimed");

        address archivist = libraryContract.getUploader(arweaveHash);

        uploadRewardClaimed[arweaveHash] = true;
        // we send 50 alex to archivist from treasury. we use transferFrom because treasury is the one sending the tokens, so treasury must approve this contract to spend UPLOAD_REWARD before calling this function.
        // need to change address(this) to treasury, because we are sending from treasury, not from this contract balance
        tokenContract.transferFrom(treasury, archivist, UPLOAD_REWARD);

        // we emit the event for the frontend to track successful distribution of upload reward
        emit UploadRewardDistributed(arweaveHash, archivist, UPLOAD_REWARD);
    }



    // --- Claim Functions (Pull Pattern) ---

    function claimArchivistRewards() external nonReentrant whenNotPaused {
        uint256 amount = pendingArchivistRewards[msg.sender];
        require(amount > 0, "Nothing to claim");

        // reset earned rewards before transfer to prevent reentrancy issues
        pendingArchivistRewards[msg.sender] = 0;
        // means we are sending from this contract balance, so we use transfer, not transferFrom
        tokenContract.transfer(msg.sender, amount);

        emit RewardClaimed(msg.sender, amount);
    }

    function claimLibrarianRewards() external nonReentrant whenNotPaused updateReward(msg.sender) {
        uint256 amount = librarianEarned[msg.sender];
        require(amount > 0, "Nothing to claim");

        // reset earned rewards before transfer to prevent reentrancy issues
        librarianEarned[msg.sender] = 0;
        tokenContract.transfer(msg.sender, amount);

        emit RewardClaimed(msg.sender, amount);
    }

    // --- Admin Functions ---

    function setStakeContract(address _stakeContract) external onlyOwner {
        require(_stakeContract != address(0), "Zero address");
        stakeContract = AlexandriaStake(_stakeContract);
    }

    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "Zero address");
        treasury = _treasury;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/Rent.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./library.sol";
import "./token.sol";

// This contract is the on-chain permission registry for Alexandria rentals.

interface IAlexandriaPayment {
    function processRentalPayment(string memory arweaveHash, address renter, uint256 amount) external;
}

contract AlexandriaRent is Ownable, Pausable {

    AlexandriaLibrary public libraryContract;
    AlexandriaToken public tokenContract;
    IAlexandriaPayment public paymentContract;

    // Valid rental durations
    uint256 public constant DURATION_1DAY = 1 days;
    uint256 public constant DURATION_7DAY = 7 days;
    uint256 public constant DURATION_30DAY = 30 days;

    // arweaveHash → renter address → expiry timestamp
    // Supports multiple renters per book simultaneously
    mapping(string => mapping(address => uint256)) public rentals;

    // Archivist-set price per book in ALEX tokens
    mapping(string => uint256) public bookPrices;

    // Addresses banned from renting (caught leaking)
    mapping(address => bool) public blacklisted;

    // Books blocked from new rentals (existing rentals still honoured)
    mapping(string => bool) public delisted;

    // Events
    event BookRented(string indexed arweaveHash, address indexed renter, uint256 expiry, uint256 duration);
    event BookPriceSet(string indexed arweaveHash, uint256 price);
    event AddressBlacklisted(address indexed renter);
    event BookDelisted(string indexed arweaveHash);
    event PaymentContractSet(address indexed paymentContract);

    constructor(address _libraryAddress, address _tokenAddress) Ownable(msg.sender) {
        libraryContract = AlexandriaLibrary(_libraryAddress);
        tokenContract = AlexandriaToken(_tokenAddress);
    }

    function setPaymentContract(address _paymentContract) external onlyOwner {
        require(_paymentContract != address(0), "Zero address");
        paymentContract = IAlexandriaPayment(_paymentContract);
        emit PaymentContractSet(_paymentContract);
    }

    function isRentalActive(string memory arweaveHash, address renter) public view whenNotPaused returns (bool) {
         return rentals[arweaveHash][renter] > block.timestamp && !blacklisted[renter];
    }

    function setBookPrice(string memory arweaveHash, uint256 price) external whenNotPaused {
        require(libraryContract.getUploader(arweaveHash) == msg.sender, "Not the Archivist");
        require(libraryContract.getUploadStatus(arweaveHash) == AlexandriaLibrary.UploadStatus.Approved, "Book is not approved");
        require(price > 0, "Price must be greater than 0");


        bookPrices[arweaveHash] = price;

        emit BookPriceSet(arweaveHash, price);
    }

    function rentBook(string memory arweaveHash, uint256 duration) external whenNotPaused {
        require(!blacklisted[msg.sender], "Address is blacklisted");
        require(libraryContract.getUploader(arweaveHash) != msg.sender, "Archivist cannot rent own book");
        require(!delisted[arweaveHash], "Book delisted");
        require(libraryContract.getUploadStatus(arweaveHash) == AlexandriaLibrary.UploadStatus.Approved, "Book not approved");
        require(bookPrices[arweaveHash] > 0, "Book has no price set");
        require(duration == DURATION_1DAY || duration == DURATION_7DAY || duration == DURATION_30DAY, "Invalid rental duration");
        require(rentals[arweaveHash][msg.sender] <= block.timestamp, "Active rental already exists");

        // Daily rate: bookPrices stores price per day, multiply by number of days
        uint256 daysCount = duration / 1 days;
        uint256 totalPrice = bookPrices[arweaveHash] * daysCount;

        require(address(paymentContract) != address(0), "Payment contract not set");
        tokenContract.transferFrom(msg.sender, address(paymentContract), totalPrice);

        uint256 expiry = block.timestamp + duration;
        rentals[arweaveHash][msg.sender] = expiry;

        paymentContract.processRentalPayment(arweaveHash, msg.sender, totalPrice);
        emit BookRented(arweaveHash, msg.sender, expiry, duration);
    }

    function blacklistAddress(address renter) external onlyOwner {
        require(renter != address(0), "Invalid address");
        require(!blacklisted[renter], "Already blacklisted");

        blacklisted[renter] = true;

        emit AddressBlacklisted(renter);
    }

    function delistBook(string memory arweaveHash) external onlyOwner {
        require(libraryContract.uploadExists(arweaveHash), "Book not found");
        require(!delisted[arweaveHash], "Already delisted");

        delisted[arweaveHash] = true;

        emit BookDelisted(arweaveHash);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

